import json
import re
from datetime import date

_DAY_PATTERN = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")


def _valid_day(value):
    """Return True only for a valid ``YYYY-MM-DD`` calendar-day string."""
    if not isinstance(value, str):
        return False
    match = _DAY_PATTERN.fullmatch(value)
    if match is None:
        return False
    year, month, day = (int(part) for part in match.groups())
    try:
        date(year, month, day)
    except ValueError:
        return False
    return True


def _validate_row(index, row):
    """Validate a single row, raising ValueError with a positional message."""
    if not isinstance(row, dict):
        raise ValueError(f"row {index} must be a JSON object")
    tenant = row.get("tenant")
    if not isinstance(tenant, str) or not tenant:
        raise ValueError(f"row {index} tenant must be a nonempty string")
    amount_cents = row.get("amount_cents")
    # ``bool`` is a subclass of ``int`` but is not an integer amount.
    if type(amount_cents) is not int:
        raise ValueError(f"row {index} amount_cents must be an integer")
    day = row.get("day")
    if not _valid_day(day):
        raise ValueError(f"row {index} day must be a valid YYYY-MM-DD string")


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    if not isinstance(text, str):
        raise ValueError("input must be a JSON string")
    try:
        rows = json.loads(text)
    except json.JSONDecodeError as error:
        raise ValueError(f"invalid JSON: {error}") from error
    if not isinstance(rows, list):
        raise ValueError("input must be a JSON array of rows")

    total_cents = 0
    first_day = None
    last_day = None
    for index, row in enumerate(rows):
        _validate_row(index, row)
        total_cents += row["amount_cents"]
        day = row["day"]
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        "row_count": len(rows),
        "total_cents": total_cents,
        "first_day": first_day,
        "last_day": last_day,
    }
